import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`etsy-store`,heroTitle:`Optimize your Etsy listings in minutes`,heroSubtitle:`Perplexity Computer analyzes your shop, rewrites every title and tag, and delivers ad-ready listings — automatically.`,inputUrlCta:`Optimize my shop`,inputUrlPlaceholder:`www.etsy.com/shop/yourshop`,inputUrlPrefill:`Go to {url} and optimize every listing in this Etsy shop for search and Etsy Ads. For each listing: (1) Analyze the current title, tags, and description against Etsy search best practices, (2) Research the top-performing competitor listings for each product category, (3) Rewrite the title using high-volume Etsy search terms — front-load the most important keywords, keep under 140 characters, (4) Generate a full set of 13 tags per listing using long-tail buyer-intent keywords, (5) Write an optimized description with natural keyword placement and a compelling hook, (6) Score each listing's ad relevance before and after optimization. Deliver a spreadsheet with one row per listing showing: original title, new title, original tags, new tags, new description, relevance score before, relevance score after, and top competitor keywords.`,heroOverlaySteps:[`Analyzing every listing in your shop for titles, tags, and descriptions`,`Researching top competitor listings and high-volume Etsy search terms`,`Rewriting titles and generating 13 optimized tags per listing`,`Optimized listings with before/after scores — ready to update`],generatingSteps:[`Visiting {url} to extract your listings, titles, tags, and descriptions`,`Designing an agent to research Etsy search trends and competitor keywords`,`Configuring title rewrites and tag generation for every listing`,`Setting up deliverable spreadsheet with before/after comparison and scores`],featureSectionTitle:`From shop to optimized listings`,featureCardTitles:[`Connects to your store tools`,`Listings ready to update`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Shopify, Google Sheets, Canva, Airtable — Computer plugs into your tools so optimized listings flow straight from research to your shop.`,`Rewritten titles. Optimized tags. Ad-ready descriptions. Computer delivers a spreadsheet you can copy straight into your shop.`],capabilitySectionTitle:`Your Etsy SEO team, on demand`,capabilitySectionSubtitle:`Paste your shop URL, get back fully optimized listings.`,capabilityCards:[{title:`Listing Audit`,description:`Computer analyzes every listing in your shop — titles, tags, descriptions, and images — and scores each one against Etsy search best practices.`},{title:`Keyword Research`,description:`Computer finds high-volume Etsy search terms and long-tail buyer-intent keywords specific to your product categories.`},{title:`Title & Tag Rewrites`,description:`Computer rewrites every title with front-loaded keywords and generates a full set of 13 optimized tags per listing.`},{title:`Competitor Analysis`,description:`Computer researches top-performing competitor listings — extracting their keywords, pricing, and positioning so you can outrank them.`},{title:`Learns Your Shop`,description:`Computer remembers your product categories, brand style, and past optimizations — so every update builds on what came before.`},{title:`Monthly Refreshes`,description:`Computer monitors Etsy search trends and competitor changes — and alerts you when listings need a keyword refresh.`}]});export{t as default};
